use proc_macro::TokenStream;
use proc_macro2::Span;
use quote::quote;
use syn::parse::{Parse, ParseStream};
use syn::{parse_macro_input, Data, DeriveInput, Fields, Ident, Token, Type};

#[proc_macro_derive(CodeGen)]
pub fn derive_codegen(input: TokenStream) -> TokenStream {
    let input = parse_macro_input!(input as DeriveInput);
    match expand_codegen(&input) {
        Ok(tokens) => tokens.into(),
        Err(err) => err.to_compile_error().into(),
    }
}

fn expand_codegen(input: &DeriveInput) -> syn::Result<proc_macro2::TokenStream> {
    let name = &input.ident;
    let field_names = field_names(&input.data)
        .into_iter()
        .map(|ident| ident.to_string())
        .collect::<Vec<_>>();
    let field_count = field_names.len();

    Ok(quote! {
        impl #name {
            pub const FIELD_COUNT: usize = #field_count;

            pub fn field_names() -> &'static [&'static str] {
                &[#(#field_names),*]
            }
        }
    })
}

fn field_names(data: &Data) -> Vec<&Ident> {
    let fields = match data {
        Data::Struct(data) => &data.fields,
        Data::Enum(data) => {
            return data
                .variants
                .iter()
                .filter_map(|variant| variant.ident.clone().into())
                .map(|ident| Box::leak(Box::new(ident)))
                .collect();
        }
        Data::Union(_) => return Vec::new(),
    };

    match fields {
        Fields::Named(fields) => fields
            .named
            .iter()
            .filter_map(|field| field.ident.as_ref())
            .collect(),
        Fields::Unnamed(_) | Fields::Unit => Vec::new(),
    }
}

struct StructSpec {
    name: Ident,
    fields: Vec<(Ident, Type)>,
}

impl Parse for StructSpec {
    fn parse(input: ParseStream) -> syn::Result<Self> {
        let name: Ident = input.parse()?;
        let content;
        syn::braced!(content in input);

        let mut fields = Vec::new();
        while !content.is_empty() {
            let field: Ident = content.parse()?;
            content.parse::<Token![:]>()?;
            let ty: Type = content.parse()?;
            fields.push((field, ty));

            if content.peek(Token![,]) {
                content.parse::<Token![,]>()?;
            } else {
                break;
            }
        }

        Ok(StructSpec { name, fields })
    }
}

#[proc_macro]
pub fn make_struct(input: TokenStream) -> TokenStream {
    let spec = parse_macro_input!(input as StructSpec);
    let name = &spec.name;
    let field_names: Vec<&Ident> = spec.fields.iter().map(|(ident, _)| ident).collect();
    let field_types: Vec<&Type> = spec.fields.iter().map(|(_, ty)| ty).collect();

    let generated = quote! {
        #[derive(Debug, Clone, PartialEq, Eq)]
        pub struct #name {
            #(pub #field_names: #field_types),*
        }

        impl #name {
            pub fn new(#(#field_names: #field_types),*) -> Self {
                Self { #(#field_names),* }
            }

            pub fn field_count() -> usize {
                [#(#field_names),*].len()
            }
        }
    };

    generated.into()
}

#[proc_macro]
pub fn sum_impl(input: TokenStream) -> TokenStream {
    let spec = parse_macro_input!(input as StructSpec);

    let variants = spec.fields.iter().map(|(ident, ty)| {
        let ident = Ident::new(&ident.to_string(), Span::call_site());
        quote! { Self::#ident(value) => f64::from(*value) }
    });

    let enum_name = &spec.name;
    let variant_idents: Vec<&Ident> = spec.fields.iter().map(|(ident, _)| ident).collect();
    let variant_types: Vec<&Type> = spec.fields.iter().map(|(_, ty)| ty).collect();

    quote! {
        pub enum #enum_name {
            #(#variant_idents(#variant_types)),*
        }

        impl #enum_name {
            pub fn to_f64(&self) -> f64 {
                match self {
                    #(#variants),*
                }
            }
        }
    }
    .into()
}

